import { useEffect, useState } from "react";
import socket from "../socket";
import api from "../api";
import { useToast } from "../context/ToastContext";
import Skeleton from "../components/Skeleton";
import "../components/skeleton.css";

export default function Provider() {
  const [req, setReq] = useState(null);
  const [providerId, setProviderId] = useState("");
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const { addToast } = useToast();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        const localId = decoded.id;
        setProviderId(localId);
        // send object with providerId for consistency
        socket.emit("provider-online", { providerId: localId });
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }
    
    socket.on("booking-created", (data) => {
      // Use the localId captured above to avoid stale closure on providerId state
      const matchId = (typeof data === 'object' && data.providerId) ? data.providerId : null;
      if (!matchId || matchId === (localId || providerId)) {
        setReq(data.booking || data);
      }
    });

    return () => {
      socket.off("booking-created");
    };
  }, []);

  // Emit live location while provider is online
  useEffect(() => {
    if (!providerId || !navigator.geolocation) return;

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        const payload = {
          providerId,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };
        socket.emit("provider-location", payload);
      },
      (err) => console.warn("Provider geolocation error:", err),
      { enableHighAccuracy: true }
    );

    return () => navigator.geolocation.clearWatch(watchId);
  }, [providerId]);

  const handleAccept = () => {
    socket.emit("booking-response", { bookingId: req && req._id, status: "accepted", providerId: providerId });
    setReq(null);
  };

  const handleReject = () => {
    socket.emit("booking-response", { bookingId: req && req._id, status: "rejected", providerId: providerId });
    setReq(null);
  };

  if (!req) {
    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="dashboard-logo">🚀 FastAid</div>
          <button className="logout-btn" onClick={() => {
            localStorage.removeItem("token");
            window.location.href = "/";
          }}>
            Logout
          </button>
        </header>
        <div className="dashboard-content">
          <h1 className="dashboard-title">Provider Dashboard 🛠️</h1>
          <p className="dashboard-subtitle">Manage your service requests</p>
          
            <div className="no-requests">
              <div className="no-requests-icon">🔔</div>
              <div className="no-requests-text">No new service requests</div>
              <p style={{ marginTop: '10px', color: '#6B7280' }}>Waiting for new bookings...</p>
              <div style={{ marginTop: 14 }}>
                <Skeleton count={2} height="80px" />
              </div>
            </div>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="dashboard-logo">🚀 FastAid</div>
        <button className="logout-btn" onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}>
          Logout
        </button>
      </header>
      <div className="dashboard-content">
        <h1 className="dashboard-title">New Service Request 🔔</h1>
        
        <div className="provider-request-card">
          <div className="provider-request-title">Service: {req.serviceName}</div>
          <p style={{ fontSize: '16px', marginBottom: '10px' }}>📍 Location: {req.location}</p>
          <p style={{ fontSize: '14px', opacity: 0.9 }}>Customer ID: {req.userId}</p>
          
          <div className="provider-buttons">
            <button className="provider-btn provider-btn-accept" onClick={handleAccept}>
              ✅ Accept Request
            </button>
            <button className="provider-btn provider-btn-reject" onClick={handleReject}>
              ❌ Reject Request
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
